+            final var fullGC = new Thread(WB::fullGC);
+            try (var _ = new TestHelpers.ScopedListener()) {
+                fullGC.start();
+                WB.shenandoahOldMarkGC(5);
+
+                fullGC.join(10000);
+            } catch (IOException e) {
+                throw new RuntimeException(e);
+            }
+        }
+    }
